// Texts of the lesson warm-ups (tools/lesson_ramps.js), keyed; each { ja, en, zh, ko, es, fr, pt, de, hi, ar }.
// Missing languages fall back to English when lessons.json is built.
module.exports = {
  'b_step.e.t': { ja: '動き方：内側か、同じ輪の上', en: 'How pieces move: inwards or along the ring', zh: '走法：向内或沿同一圈', ko: '이동: 안쪽으로, 또는 같은 고리 위로', es: 'Cómo se mueven las piezas: hacia dentro o por el anillo', fr: 'Déplacement : vers l’intérieur ou le long de l’anneau', pt: 'Como as peças andam: para dentro ou pelo anel', de: 'Wie die Steine ziehen: nach innen oder auf dem Ring', hi: 'गोटियाँ कैसे चलती हैं: अंदर या घेरे पर', ar: 'كيف تتحرك القطع: إلى الداخل أو على الحلقة', ru: 'Как ходят фигуры: внутрь или по кольцу', 'zh-TW': '棋子的走法：往內或沿圈', id: 'Cara bidak bergerak: ke dalam atau di cincin', tr: 'Taşlar nasıl hareket eder: içeri ya da halka boyunca' },
  'b_step.e.b': { ja: '駒は<b>となりの空いているマスへ1歩</b>。行けるのは<b>同じ輪の上（横）</b>か<b>1つ内側の輪</b>だけで、<b>外側へは戻れません</b>（赤い矢印）。\n一度内側へ入った駒は二度と外へ出られません。どの駒をいつ内側へ進めるかが勝負です。', en: 'A piece makes <b>one step to an empty neighbouring cell</b>: <b>along its ring (sideways)</b> or <b>into the next ring inwards</b> — <b>never outwards</b> (red arrows).\nOnce a piece has moved in it can never go back out, so which piece to bring in, and when, is the whole game.', zh: '棋子<b>走一步到相邻的空格</b>：只能<b>沿同一圈（横走）</b>或<b>进入内侧的下一圈</b>，<b>不能退回外侧</b>（红色箭头）。\n一旦进入内侧就再也出不去。哪枚棋子何时向内前进，决定胜负。', ko: '말은 <b>이웃한 빈칸으로 한 걸음</b>. 갈 수 있는 곳은 <b>같은 고리 위(옆)</b>나 <b>한 칸 안쪽 고리</b>뿐이고, <b>바깥으로는 돌아갈 수 없습니다</b>(빨간 화살표).\n한번 안으로 들어간 말은 다시는 밖으로 못 나옵니다. 어느 말을 언제 안으로 보낼지가 승부입니다.', es: 'Una pieza da <b>un paso a una casilla vecina vacía</b>: <b>por su anillo (de lado)</b> o <b>al anillo siguiente hacia dentro</b>, <b>nunca hacia fuera</b> (flechas rojas).\nUna vez que entra, ya no puede volver a salir: qué pieza meter, y cuándo, es todo el juego.', fr: 'Une pièce fait <b>un pas vers une case voisine vide</b> : <b>le long de son anneau (de côté)</b> ou <b>vers l’anneau suivant, à l’intérieur</b> — <b>jamais vers l’extérieur</b> (flèches rouges).\nUne fois entrée, une pièce ne peut plus ressortir : quelle pièce faire entrer, et quand, c’est tout le jeu.', pt: 'Uma peça dá <b>um passo para uma casa vizinha vazia</b>: <b>pelo seu anel (para o lado)</b> ou <b>para o anel seguinte, para dentro</b> — <b>nunca para fora</b> (setas vermelhas).\nDepois que uma peça entra, nunca mais sai; então qual peça levar para dentro, e quando, é o jogo todo.', de: 'Ein Stein macht <b>einen Schritt auf ein freies Nachbarfeld</b>: <b>auf seinem Ring (seitwärts)</b> oder <b>in den nächsten Ring nach innen</b> — <b>nie nach außen</b> (rote Pfeile).\nIst ein Stein einmal nach innen gezogen, kommt er nie wieder hinaus; welchen Stein man wann hineinzieht, ist das ganze Spiel.', hi: 'गोटी <b>एक कदम पड़ोस के खाली खाने पर</b> चलती है: <b>अपने घेरे पर (बगल में)</b> या <b>अंदर के अगले घेरे में</b> — <b>कभी बाहर नहीं</b> (लाल तीर)।\nएक बार अंदर गई गोटी कभी बाहर नहीं लौट सकती, इसलिए कौन-सी गोटी कब अंदर लाएँ, यही पूरा खेल है।', ar: 'تخطو القطعة <b>خطوة واحدة إلى خانة مجاورة فارغة</b>: <b>على حلقتها (جانبيًا)</b> أو <b>إلى الحلقة التالية نحو الداخل</b> — <b>ولا تتحرك إلى الخارج أبدًا</b> (الأسهم الحمراء).\nبعد أن تدخل القطعة لا يمكنها الخروج أبدًا، فأي قطعة تدخل ومتى هو جوهر اللعبة كلها.', ru: 'Фигура делает <b>один шаг на пустую соседнюю клетку</b>: <b>по своему кольцу (вбок)</b> или <b>на следующее кольцо внутрь</b> — <b>никогда наружу</b> (красные стрелки).\nВошедшая внутрь фигура уже не выйдет обратно, поэтому вся игра в том, какую фигуру и когда вводить.', 'zh-TW': '棋子<b>往相鄰的空格走一步</b>：<b>沿所在的圈（橫向）</b>或<b>進入內側的下一圈</b> — <b>絕不往外</b>（紅色箭頭）。\n棋子一旦進到內側就再也出不去，所以讓哪枚棋子、在什麼時候進去，就是整盤棋的關鍵。', id: 'Bidak melangkah <b>satu langkah ke petak tetangga yang kosong</b>: <b>di sepanjang cincinnya (ke samping)</b> atau <b>ke cincin berikutnya di dalam</b> — <b>tidak pernah ke luar</b> (panah merah).\nBidak yang sudah masuk tidak bisa keluar lagi, jadi bidak mana yang dimasukkan, dan kapan, itulah inti permainannya.', tr: 'Bir taş <b>boş komşu kareye bir adım</b> atar: <b>halkası boyunca (yana)</b> ya da <b>içerideki bir sonraki halkaya</b> — <b>asla dışarı değil</b> (kırmızı oklar).\nİçeri giren taş bir daha dışarı çıkamaz; bu yüzden hangi taşı ne zaman içeri sokacağın oyunun ta kendisidir.' },
  'b_step.y.g': { ja: 'どれか1枚を内側の輪へ進めよう。', en: 'Move any piece one ring inwards.', zh: '把任意一枚棋子向内走一圈。', ko: '아무 말이나 하나를 한 고리 안쪽으로 옮기세요.', es: 'Mueve cualquier pieza un anillo hacia dentro.', fr: 'Avancez n’importe quelle pièce d’un anneau vers l’intérieur.', pt: 'Mova qualquer peça um anel para dentro.', de: 'Ziehe einen beliebigen Stein einen Ring nach innen.', hi: 'किसी भी गोटी को एक घेरा अंदर ले जाएँ।', ar: 'حرّك أي قطعة حلقة واحدة إلى الداخل.', ru: 'Передвиньте любую фигуру на одно кольцо внутрь.', 'zh-TW': '把任一枚棋子往內走一圈。', id: 'Gerakkan bidak mana saja satu cincin ke dalam.', tr: 'Herhangi bir taşı bir halka içeri oynat.' },
  'b_step.y.h': { ja: '輪の番号が1つ小さいマスへ。外の輪は5、王座のとなりが1です。', en: 'Onto a cell whose ring number is one smaller — the edge is ring 5, the cells round the throne ring 1.', zh: '走到圈编号小1的格子。外圈是5，王座旁是1。', ko: '고리 번호가 1 작은 칸으로. 바깥 고리가 5, 왕좌 옆이 1입니다.', es: 'A una casilla con el número de anillo uno menor: el borde es el anillo 5 y las casillas junto al trono, el anillo 1.', fr: 'Sur une case dont le numéro d’anneau est inférieur d’un — le bord est l’anneau 5, les cases autour du trône l’anneau 1.', pt: 'Para uma casa com número de anel um menor — a borda é o anel 5, as casas ao redor do trono o anel 1.', de: 'Auf ein Feld mit um eins kleinerer Ringnummer — der Rand ist Ring 5, die Felder um den Thron Ring 1.', hi: 'ऐसे खाने पर जिसका घेरा नंबर एक कम हो — बाहरी घेरा 5 है, सिंहासन के पास के खाने घेरा 1।', ar: 'إلى خانة رقم حلقتها أصغر بواحد — الحلقة الخارجية هي 5، والخانات حول العرش هي الحلقة 1.', ru: 'На клетку с номером кольца на один меньше — край это кольцо 5, клетки вокруг трона — кольцо 1.', 'zh-TW': '走到圈號少一的格子 — 外圈是第5圈，王座周圍是第1圈。', id: 'Ke petak dengan nomor cincin lebih kecil satu — tepi adalah cincin 5, petak di sekitar takhta cincin 1.', tr: 'Halka numarası bir küçük olan kareye — kenar 5. halka, tahtın çevresindeki kareler 1. halka.' },
  'b_step.y.y': { ja: 'その調子。内側へ進むほど王座に近づきます。', en: 'That’s it — every step inwards brings you closer to the throne.', zh: '很好。越向内走，离王座越近。', ko: '좋아요. 안쪽으로 갈수록 왕좌에 가까워집니다.', es: 'Eso es: cada paso hacia dentro te acerca al trono.', fr: 'C’est ça — chaque pas vers l’intérieur vous rapproche du trône.', pt: 'Isso — cada passo para dentro aproxima você do trono.', de: 'Genau — jeder Schritt nach innen bringt dich näher an den Thron.', hi: 'बिल्कुल — अंदर की ओर हर कदम आपको सिंहासन के क़रीब लाता है।', ar: 'هكذا — كل خطوة إلى الداخل تقرّبك من العرش.', ru: 'Верно — каждый шаг внутрь приближает вас к трону.', 'zh-TW': '沒錯 — 每往內一步，就離王座更近。', id: 'Benar — setiap langkah ke dalam membawamu lebih dekat ke takhta.', tr: 'İşte bu — içeri her adım seni tahta yaklaştırır.' },
  'b_throne.e.t': { ja: '王座に入れるのは女王だけ', en: 'Only the queen may enter the throne', zh: '只有女王能进入王座', ko: '왕좌에는 여왕만 들어갈 수 있다', es: 'Solo la reina puede entrar en el trono', fr: 'Seule la reine peut entrer sur le trône', pt: 'Só a rainha pode entrar no trono', de: 'Nur die Königin darf den Thron betreten', hi: 'सिंहासन पर सिर्फ़ रानी जा सकती है', ar: 'لا يدخل العرش إلا الملكة', ru: 'На трон может встать только королева', 'zh-TW': '只有女王能進入王座', id: 'Hanya ratu yang boleh masuk takhta', tr: 'Tahta yalnızca kraliçe girebilir' },
  'b_throne.e.b': { ja: '中央の王座（★）に入れるのは<b>女王（六角形の駒）だけ</b>。ガードは王座のとなり（1の輪）までです。\n勝つには<b>女王が王座に座り、その周りの6マスを自分のガード6枚で囲む</b>こと。まず女王を王座へ運びましょう。', en: 'Only the <b>queen (the hexagonal piece)</b> may step onto the throne (★) in the middle. Guards go no further than ring 1, round it.\nTo win, your <b>queen sits on the throne and your six guards fill the six cells round her</b>. So the queen goes in first.', zh: '中央的王座（★）只有<b>女王（六角形的棋子）</b>能进入。卫兵最多只能走到王座旁（第1圈）。\n获胜条件是<b>女王坐上王座，并用自己的6个卫兵占满她周围的6格</b>。所以先把女王送上王座。', ko: '중앙 왕좌(★)에는 <b>여왕(육각형 말)만</b> 들어갈 수 있습니다. 호위병은 왕좌 옆(1번 고리)까지입니다.\n이기려면 <b>여왕이 왕좌에 앉고 둘레 6칸을 내 호위병 6개로 둘러싸야</b> 합니다. 먼저 여왕을 왕좌로 보내세요.', es: 'Solo la <b>reina (la pieza hexagonal)</b> puede pisar el trono (★) del centro. Los guardias no pasan del anillo 1, a su alrededor.\nPara ganar, tu <b>reina se sienta en el trono y tus seis guardias ocupan las seis casillas que la rodean</b>. Así que primero entra la reina.', fr: 'Seule la <b>reine (la pièce hexagonale)</b> peut monter sur le trône (★) au centre. Les gardes ne dépassent pas l’anneau 1, autour.\nPour gagner, votre <b>reine siège sur le trône et vos six gardes occupent les six cases autour d’elle</b>. La reine entre donc en premier.', pt: 'Só a <b>rainha (a peça hexagonal)</b> pode pisar no trono (★) do centro. Os guardas não passam do anel 1, ao redor dele.\nPara vencer, sua <b>rainha se senta no trono e seus seis guardas ocupam as seis casas ao redor dela</b>. Então a rainha entra primeiro.', de: 'Nur die <b>Königin (der sechseckige Stein)</b> darf den Thron (★) in der Mitte betreten. Wachen kommen höchstens bis Ring 1, rund um ihn.\nZum Sieg <b>sitzt deine Königin auf dem Thron und deine sechs Wachen besetzen die sechs Felder um sie</b>. Also kommt die Königin zuerst hinein.', hi: 'बीच के सिंहासन (★) पर सिर्फ़ <b>रानी (षट्कोणीय गोटी)</b> जा सकती है। रक्षक उसके चारों ओर घेरा 1 से आगे नहीं जाते।\nजीतने के लिए <b>आपकी रानी सिंहासन पर बैठे और आपके छह रक्षक उसके चारों ओर के छह खाने भरें</b>। इसलिए पहले रानी अंदर जाती है।', ar: 'لا يدخل العرش (★) في الوسط إلا <b>الملكة (القطعة السداسية)</b>. لا يتجاوز الحراس الحلقة 1 المحيطة به.\nللفوز <b>تجلس ملكتك على العرش ويملأ حراسك الستة الخانات الست حولها</b>. لذلك تدخل الملكة أولًا.', ru: 'Только <b>королева (шестиугольная фигура)</b> может встать на трон (★) в центре. Стражи доходят лишь до кольца 1 вокруг него.\nДля победы <b>королева сидит на троне, а шесть стражей занимают шесть клеток вокруг неё</b>. Поэтому королева входит первой.', 'zh-TW': '只有<b>女王（六角形的棋子）</b>能走上中央的王座（★）。衛兵最多只能到王座周圍的第1圈。\n獲勝條件是<b>女王坐在王座上，六名衛兵占滿她周圍的六格</b>。所以女王要先進去。', id: 'Hanya <b>ratu (bidak heksagonal)</b> yang boleh naik ke takhta (★) di tengah. Pengawal paling jauh sampai cincin 1 di sekelilingnya.\nUntuk menang, <b>ratumu duduk di takhta dan enam pengawalmu mengisi enam petak di sekelilingnya</b>. Jadi ratu masuk lebih dulu.', tr: 'Ortadaki tahta (★) yalnızca <b>kraliçe (altıgen taş)</b> çıkabilir. Muhafızlar en fazla çevresindeki 1. halkaya kadar gider.\nKazanmak için <b>kraliçen tahtta oturur ve altı muhafızın çevresindeki altı kareyi doldurur</b>. Bu yüzden önce kraliçe girer.' },
  'b_throne.y.g': { ja: '女王を王座へ進めよう。', en: 'Move your queen onto the throne.', zh: '把女王走上王座。', ko: '여왕을 왕좌로 옮기세요.', es: 'Lleva tu reina al trono.', fr: 'Amenez votre reine sur le trône.', pt: 'Leve sua rainha ao trono.', de: 'Ziehe deine Königin auf den Thron.', hi: 'अपनी रानी को सिंहासन पर ले जाएँ।', ar: 'حرّك ملكتك إلى العرش.', ru: 'Поставьте королеву на трон.', 'zh-TW': '讓女王走上王座。', id: 'Gerakkan ratumu ke takhta.', tr: 'Kraliçeni tahta oynat.' },
  'b_throne.y.h': { ja: '女王は王座のとなりにいます。', en: 'Your queen stands next to the throne.', zh: '你的女王就在王座旁。', ko: '여왕이 왕좌 옆에 있습니다.', es: 'Tu reina está junto al trono.', fr: 'Votre reine se trouve à côté du trône.', pt: 'Sua rainha está ao lado do trono.', de: 'Deine Königin steht neben dem Thron.', hi: 'आपकी रानी सिंहासन के पास खड़ी है।', ar: 'ملكتك تقف بجوار العرش.', ru: 'Ваша королева стоит рядом с троном.', 'zh-TW': '你的女王就在王座旁。', id: 'Ratumu berdiri di sebelah takhta.', tr: 'Kraliçen tahtın yanında duruyor.' },
  'b_throne.y.y': { ja: '王座に座りました。あとはガードで周りを囲むだけです。', en: 'She is on the throne — now the guards close in round her.', zh: '坐上王座了。接下来只要用卫兵围住周围。', ko: '왕좌에 앉았습니다. 이제 호위병으로 둘레를 채우면 됩니다.', es: 'Ya está en el trono: ahora los guardias cierran el cerco a su alrededor.', fr: 'Elle est sur le trône — maintenant les gardes se resserrent autour d’elle.', pt: 'Ela está no trono — agora os guardas fecham o cerco ao redor dela.', de: 'Sie sitzt auf dem Thron — jetzt schließen die Wachen den Ring um sie.', hi: 'वह सिंहासन पर है — अब रक्षक उसके चारों ओर घेरा कसेंगे।', ar: 'إنها على العرش — والآن يُطبق الحراس الحلقة حولها.', ru: 'Она на троне — теперь стражи сходятся вокруг неё.', 'zh-TW': '她坐上王座了 — 接著讓衛兵圍上來。', id: 'Ia di takhta — sekarang pengawal merapat di sekelilingnya.', tr: 'Tahtta — şimdi muhafızlar çevresinde toplanıyor.' },
  'b_capture.e.t': { ja: '捕獲：一直線にはさむ', en: 'Capture: sandwich in a line', zh: '吃子：在一条直线上夹住', ko: '잡기: 한 줄로 끼우기', es: 'Captura: encerrar en línea', fr: 'Capture : la tenaille en ligne', pt: 'Captura: cercar em linha', de: 'Schlagen: in einer Linie einschließen', hi: 'पकड़: एक रेखा में फँसाना', ar: 'الأسر: المحاصرة على خط', ru: 'Взятие: зажать на линии', 'zh-TW': '吃子：在一直線上夾住', id: 'Menangkap: jepit dalam satu garis', tr: 'Alma: bir çizgide sıkıştır' },
  'b_capture.e.b': { ja: '動かした駒と自分のもう1枚で、相手の駒を<b>一直線にはさむ</b>と捕獲です（金の矢印→赤い印）。\n捕まった駒は盤から消えず、<b>持ち主が次の手番で置き直さなければなりません</b>。ガードは外周へ、女王は王座以外の好きな空きマスへ。相手は1手損をするうえ、外へ戻されます。', en: 'If the piece you move and another of yours <b>sandwich an enemy piece in a straight line</b>, it is captured (gold arrow → red mark).\nA captured piece does not leave the board: <b>its owner must use the next turn to relocate it</b> — a guard to the edge, the queen to any empty cell but the throne. That costs a whole move and sends the guard back out.', zh: '用走动的棋子和自己的另一枚棋子<b>在一条直线上夹住敌子</b>即可吃掉（金色箭头→红色标记）。\n被吃的棋子不会离开棋盘：<b>它的主人必须用下一回合重新放置它</b>——卫兵放到外圈，女王放到王座以外的任意空格。这会花掉整整一手，还把卫兵送回外侧。', ko: '움직인 말과 내 다른 말 하나로 상대 말을 <b>한 줄로 끼우면</b> 잡습니다(금색 화살표→빨간 표시).\n잡힌 말은 판에서 사라지지 않고, <b>주인이 다음 차례에 재배치해야 합니다</b>. 호위병은 바깥 고리로, 여왕은 왕좌 외의 아무 빈칸으로. 상대는 한 수를 통째로 잃고 호위병은 밖으로 돌아갑니다.', es: 'Si la pieza que mueves y otra tuya <b>encierran una pieza enemiga en línea recta</b>, queda capturada (flecha dorada → marca roja).\nLa pieza capturada no sale del tablero: <b>su dueño debe usar el turno siguiente para recolocarla</b> — un guardia en el borde, la reina en cualquier casilla vacía salvo el trono. Eso cuesta una jugada entera y devuelve el guardia afuera.', fr: 'Si la pièce jouée et une autre des vôtres <b>prennent une pièce ennemie en tenaille sur une ligne droite</b>, elle est capturée (flèche dorée → marque rouge).\nUne pièce capturée ne quitte pas le plateau : <b>son propriétaire doit consacrer le tour suivant à la replacer</b> — un garde sur le bord, la reine sur toute case vide sauf le trône. Cela coûte un coup entier et renvoie le garde dehors.', pt: 'Se a peça que você move e outra sua <b>cercam uma peça inimiga em linha reta</b>, ela é capturada (seta dourada → marca vermelha).\nA peça capturada não sai do tabuleiro: <b>o dono precisa usar o turno seguinte para recolocá-la</b> — um guarda na borda, a rainha em qualquer casa vazia menos o trono. Isso custa um lance inteiro e manda o guarda de volta para fora.', de: 'Wenn der gezogene Stein und ein weiterer eigener <b>einen gegnerischen Stein in gerader Linie einschließen</b>, ist er geschlagen (goldener Pfeil → rote Markierung).\nEin geschlagener Stein verlässt das Brett nicht: <b>Sein Besitzer muss den nächsten Zug zum Neusetzen verwenden</b> — eine Wache an den Rand, die Königin auf ein freies Feld außer dem Thron. Das kostet einen ganzen Zug und schickt die Wache wieder hinaus.', hi: 'अगर चली गई गोटी और आपकी एक और गोटी <b>किसी विरोधी गोटी को सीधी रेखा में फँसा लें</b>, तो वह पकड़ी जाती है (सुनहरा तीर → लाल निशान)।\nपकड़ी गई गोटी बोर्ड से नहीं जाती: <b>उसके मालिक को अगली बारी उसे दोबारा रखने में लगानी होती है</b> — रक्षक बाहरी घेरे पर, रानी सिंहासन छोड़ किसी भी खाली खाने पर। इससे पूरी एक चाल जाती है और रक्षक वापस बाहर पहुँच जाता है।', ar: 'إذا حاصرت القطعة التي تحركها وقطعة أخرى لك <b>قطعة للخصم على خط مستقيم</b>، فإنها تُؤسر (السهم الذهبي ← العلامة الحمراء).\nلا تغادر القطعة المأسورة الرقعة: <b>على صاحبها أن يستخدم الدور التالي لإعادة وضعها</b> — الحارس على الحلقة الخارجية، والملكة في أي خانة فارغة عدا العرش. هذا يكلّف نقلة كاملة ويعيد الحارس إلى الخارج.', ru: 'Если ходящая фигура и другая ваша <b>зажимают фигуру соперника на прямой линии</b>, она взята (золотая стрелка → красная метка).\nВзятая фигура не покидает доску: <b>владелец обязан следующим ходом переставить её</b> — стража на край, королеву на любую пустую клетку, кроме трона. Это стоит целого хода и отправляет стража обратно наружу.', 'zh-TW': '移動的棋子和另一枚己方棋子<b>在一直線上夾住敵子</b>時，那枚棋子就被吃（金色箭頭 → 紅色標記）。\n被吃的棋子不會離開棋盤：<b>持有者下一手必須重新擺放它</b> — 衛兵放外圈，女王放王座以外的任一空格。這要花整整一手，還會把衛兵送回外側。', id: 'Jika bidak yang kamu gerakkan dan bidakmu yang lain <b>menjepit bidak lawan dalam garis lurus</b>, bidak itu tertangkap (panah emas → tanda merah).\nBidak tertangkap tidak meninggalkan papan: <b>pemiliknya harus memakai giliran berikutnya untuk memindahkannya</b> — pengawal ke tepi, ratu ke petak kosong mana saja selain takhta. Itu memakan satu langkah penuh dan mengirim pengawal kembali ke luar.', tr: 'Oynattığın taş ve başka bir taşın <b>bir rakip taşı düz bir çizgide sıkıştırırsa</b> o taş alınır (altın ok → kırmızı işaret).\nAlınan taş tahtadan çıkmaz: <b>sahibi bir sonraki turunu onu yeniden koymaya harcamalıdır</b> — muhafız kenara, kraliçe tahttan başka boş bir kareye. Bu koca bir hamleye mal olur ve muhafızı dışarı geri yollar.' },
  'b_capture.y.g': { ja: '相手の駒をはさんで捕まえよう。', en: 'Capture an enemy piece by sandwiching it.', zh: '夹住一枚敌子吃掉它。', ko: '상대 말을 끼워서 잡으세요.', es: 'Captura una pieza enemiga encerrándola.', fr: 'Capturez une pièce ennemie en la prenant en tenaille.', pt: 'Capture uma peça inimiga cercando-a.', de: 'Schlage einen gegnerischen Stein, indem du ihn einschließt.', hi: 'एक विरोधी गोटी को फँसाकर पकड़ें।', ar: 'قم بأسر قطعة للخصم بمحاصرتها.', ru: 'Возьмите фигуру соперника, зажав её.', 'zh-TW': '夾住並吃掉一枚敵子。', id: 'Tangkap bidak lawan dengan menjepitnya.', tr: 'Bir rakip taşı sıkıştırarak al.' },
  'b_capture.y.h': { ja: '自分の駒とのあいだに相手の駒が1枚だけ入る一直線を探します。', en: 'Look for a straight line with one enemy piece between your two pieces.', zh: '找一条直线，你的两枚棋子之间只有一枚敌子。', ko: '내 말 사이에 상대 말이 하나만 있는 직선을 찾으세요.', es: 'Busca una línea recta con una pieza enemiga entre dos piezas tuyas.', fr: 'Cherchez une ligne droite avec une pièce ennemie entre deux des vôtres.', pt: 'Procure uma linha reta com uma peça inimiga entre duas peças suas.', de: 'Suche eine gerade Linie mit einem gegnerischen Stein zwischen zwei deiner Steine.', hi: 'ऐसी सीधी रेखा ढूँढें जिसमें आपकी दो गोटियों के बीच एक विरोधी गोटी हो।', ar: 'ابحث عن خط مستقيم فيه قطعة واحدة للخصم بين قطعتين لك.', ru: 'Ищите прямую линию: одна фигура соперника между двумя вашими.', 'zh-TW': '找一條直線，上面是一枚敵子夾在你的兩枚棋子中間。', id: 'Cari garis lurus dengan satu bidak lawan di antara dua bidakmu.', tr: 'İki taşının arasında bir rakip taş olan düz bir çizgi ara.' },
  'b_capture.y.y': { ja: '捕獲成功！相手は次の手番を置き直しに使います。', en: 'Captured! Your opponent must spend the next turn relocating it.', zh: '吃子成功！对方下一回合要用来重新放置。', ko: '잡았습니다! 상대는 다음 차례를 재배치에 씁니다.', es: '¡Capturada! Tu rival debe gastar el próximo turno en recolocarla.', fr: 'Capturée ! L’adversaire doit consacrer son prochain tour à la replacer.', pt: 'Capturada! Seu adversário precisa gastar o próximo turno recolocando-a.', de: 'Geschlagen! Dein Gegner muss den nächsten Zug zum Neusetzen verwenden.', hi: 'पकड़ लिया! विरोधी को अगली बारी उसे दोबारा रखने में लगानी होगी।', ar: 'أُسرت! على خصمك أن ينفق الدور التالي في إعادة وضعها.', ru: 'Взято! Сопернику придётся потратить следующий ход на перестановку.', 'zh-TW': '吃到了！對手下一手必須花在重新擺放上。', id: 'Tertangkap! Lawan harus memakai giliran berikutnya untuk memindahkannya.', tr: 'Alındı! Rakip bir sonraki turunu onu yeniden koymaya harcamalı.' },
  'b_reloc.e.t': { ja: '捕まったら：置き直しの手番', en: 'When you are captured: the relocation turn', zh: '被吃之后：重新放置的回合', ko: '잡히면: 재배치 차례', es: 'Cuando te capturan: el turno de recolocación', fr: 'Quand vous êtes capturé : le tour de replacement', pt: 'Quando você é capturado: o turno de recolocação', de: 'Wenn du geschlagen wirst: der Zug zum Neusetzen', hi: 'जब आपकी गोटी पकड़ी जाए: दोबारा रखने की बारी', ar: 'حين تُؤسر قطعتك: دور إعادة الوضع', ru: 'Когда взяли вас: ход перестановки', 'zh-TW': '被吃的時候：重新擺放的一手', id: 'Saat kamu tertangkap: giliran pemindahan', tr: 'Taşın alınınca: yeniden koyma turu' },
  'b_reloc.e.b': { ja: '自分の駒が捕まると、次の手番は<b>その駒の置き直し</b>になります（ほかの駒は動かせません）。\n<b>ガードは外周（5の輪）の空いているマスへ</b>、<b>女王は王座以外のどこへでも</b>。2枚以上捕まったら、女王から先に1手に1枚ずつ。置き直す場所は<b>すぐにまた捕まらない所</b>、そして<b>早く内側へ戻れる所</b>を選びましょう。', en: 'When one of your pieces is captured, your next turn is <b>its relocation</b> (no other piece may move).\n<b>A guard goes to an empty cell of the edge (ring 5)</b>, <b>the queen to any empty cell but the throne</b>. With several captured, one per turn, the queen first. Choose a cell where it <b>cannot be captured again at once</b> and from which it <b>can come back in quickly</b>.', zh: '你的棋子被吃后，下一回合就是<b>重新放置这枚棋子</b>（不能移动其他棋子）。\n<b>卫兵放到外圈（第5圈）的空格</b>，<b>女王放到王座以外的任意空格</b>。被吃了2枚以上时，先重新放置女王，每回合1枚。重新放置的位置要选<b>不会马上再被吃</b>、又<b>能尽快回到内侧</b>的格子。', ko: '내 말이 잡히면 다음 차례는 <b>그 말의 재배치</b>입니다(다른 말은 움직일 수 없음).\n<b>호위병은 바깥 고리(5번 고리)의 빈칸으로</b>, <b>여왕은 왕좌 외의 어디로든</b>. 2개 이상 잡혔다면 여왕부터 한 차례에 하나씩. 재배치할 곳은 <b>바로 다시 잡히지 않는 곳</b>, 그리고 <b>빨리 안쪽으로 돌아올 수 있는 곳</b>을 고르세요.', es: 'Cuando capturan una de tus piezas, tu próximo turno es <b>su recolocación</b> (ninguna otra pieza puede moverse).\n<b>Un guardia va a una casilla vacía del borde (anillo 5)</b>; <b>la reina, a cualquier casilla vacía salvo el trono</b>. Si hay varias capturadas, una por turno, la reina primero. Elige una casilla donde <b>no la capturen otra vez enseguida</b> y desde la que <b>pueda volver dentro pronto</b>.', fr: 'Quand une de vos pièces est capturée, votre tour suivant est <b>son replacement</b> (aucune autre pièce ne bouge).\n<b>Un garde va sur une case vide du bord (anneau 5)</b>, <b>la reine sur toute case vide sauf le trône</b>. S’il y en a plusieurs, une par tour, la reine d’abord. Choisissez une case où elle <b>ne peut pas être recapturée aussitôt</b> et d’où elle <b>peut revenir vite vers l’intérieur</b>.', pt: 'Quando uma peça sua é capturada, seu próximo turno é <b>a recolocação dela</b> (nenhuma outra peça pode se mover).\n<b>Um guarda vai para uma casa vazia da borda (anel 5)</b>, <b>a rainha para qualquer casa vazia menos o trono</b>. Com várias capturadas, uma por turno, a rainha primeiro. Escolha uma casa onde ela <b>não possa ser capturada de novo logo</b> e de onde <b>possa voltar rápido para dentro</b>.', de: 'Wird einer deiner Steine geschlagen, ist dein nächster Zug <b>sein Neusetzen</b> (kein anderer Stein darf ziehen).\n<b>Eine Wache kommt auf ein freies Feld am Rand (Ring 5)</b>, <b>die Königin auf jedes freie Feld außer dem Thron</b>. Bei mehreren geschlagenen einer pro Zug, die Königin zuerst. Wähle ein Feld, auf dem er <b>nicht sofort wieder geschlagen werden kann</b> und von dem er <b>schnell wieder nach innen kommt</b>.', hi: 'जब आपकी कोई गोटी पकड़ी जाती है, तो आपकी अगली बारी <b>उसे दोबारा रखने</b> की होती है (कोई और गोटी नहीं चल सकती)।\n<b>रक्षक बाहरी घेरे (घेरा 5) के किसी खाली खाने पर जाता है</b>, <b>रानी सिंहासन छोड़ किसी भी खाली खाने पर</b>। कई पकड़ी गई हों तो हर बारी एक, पहले रानी। ऐसा खाना चुनें जहाँ वह <b>तुरंत फिर न पकड़ी जा सके</b> और जहाँ से <b>जल्दी अंदर लौट सके</b>।', ar: 'حين تُؤسر إحدى قطعك، يكون دورك التالي <b>إعادة وضعها</b> (لا يجوز تحريك قطعة أخرى).\n<b>يذهب الحارس إلى خانة فارغة على الحلقة الخارجية (الحلقة 5)</b>، و<b>الملكة إلى أي خانة فارغة عدا العرش</b>. إذا أُسرت عدة قطع فواحدة في كل دور، والملكة أولًا. اختر خانة <b>لا يمكن أسرها فيها فورًا من جديد</b> و<b>تعود منها سريعًا إلى الداخل</b>.', ru: 'Когда вашу фигуру взяли, ваш следующий ход — <b>её перестановка</b> (другие фигуры ходить не могут).\n<b>Страж ставится на пустую клетку края (кольцо 5)</b>, <b>королева — на любую пустую клетку, кроме трона</b>. Если взято несколько — по одной за ход, королева первой. Выберите клетку, где её <b>не возьмут сразу снова</b> и откуда она <b>быстро вернётся внутрь</b>.', 'zh-TW': '你的棋子被吃時，下一手就是<b>重新擺放它</b>（其他棋子不能動）。\n<b>衛兵放到外圈（第5圈）的空格</b>，<b>女王放到王座以外的任一空格</b>。被吃多枚時一手擺一枚，先擺女王。選一格<b>不會馬上又被吃</b>、又<b>能快速回到內側</b>的位置。', id: 'Saat bidakmu tertangkap, giliran berikutmu adalah <b>pemindahannya</b> (bidak lain tidak boleh bergerak).\n<b>Pengawal ke petak tepi yang kosong (cincin 5)</b>, <b>ratu ke petak kosong mana saja selain takhta</b>. Jika beberapa tertangkap, satu per giliran, ratu lebih dulu. Pilih petak di mana ia <b>tidak langsung tertangkap lagi</b> dan <b>bisa cepat masuk kembali</b>.', tr: 'Taşlarından biri alınınca bir sonraki turun <b>onu yeniden koymaktır</b> (başka taş oynatılamaz).\n<b>Muhafız kenardaki (5. halka) boş bir kareye</b>, <b>kraliçe tahttan başka herhangi bir boş kareye</b> konur. Birden fazla alındıysa her turda bir tane, önce kraliçe. <b>Hemen yeniden alınmayacağı</b> ve <b>çabuk içeri dönebileceği</b> bir kare seç.' },
  'b_reloc.y.g': { ja: '捕まったガードを外周へ置き直そう（すぐ捕まらない所へ）。', en: 'Relocate your captured guard to the edge (where it cannot be captured at once).', zh: '把被吃的卫兵重新放置到外圈（选不会马上被吃的格子）。', ko: '잡힌 호위병을 바깥 고리에 재배치하세요(바로 잡히지 않는 곳으로).', es: 'Recoloca tu guardia capturado en el borde (donde no lo capturen enseguida).', fr: 'Replacez votre garde capturé sur le bord (là où il ne peut pas être capturé aussitôt).', pt: 'Recoloque seu guarda capturado na borda (onde não possa ser capturado logo).', de: 'Setze deine geschlagene Wache an den Rand (wo sie nicht sofort geschlagen werden kann).', hi: 'अपने पकड़े गए रक्षक को बाहरी घेरे पर दोबारा रखें (जहाँ वह तुरंत पकड़ा न जा सके)।', ar: 'أعد وضع حارسك المأسور على الحلقة الخارجية (حيث لا يُؤسر فورًا).' },
  'b_reloc.y.h': { ja: '置けるのは外周の空きマスだけ。相手の駒2枚のあいだは避けます。', en: 'Only empty edge cells are allowed. Keep away from cells between two enemy pieces.', zh: '只能放在外圈的空格。避开两枚敌子之间的格子。', ko: '놓을 수 있는 곳은 바깥 고리의 빈칸뿐. 상대 말 2개 사이는 피하세요.', es: 'Solo valen casillas vacías del borde. Aléjate de las casillas entre dos piezas enemigas.', fr: 'Seules les cases vides du bord sont permises. Évitez les cases entre deux pièces ennemies.', pt: 'Só valem casas vazias da borda. Fique longe das casas entre duas peças inimigas.', de: 'Nur freie Randfelder sind erlaubt. Halte dich von Feldern zwischen zwei gegnerischen Steinen fern.', hi: 'सिर्फ़ बाहरी घेरे के खाली खाने चलेंगे। दो विरोधी गोटियों के बीच के खानों से दूर रहें।', ar: 'لا يُسمح إلا بخانات فارغة على الحلقة الخارجية. ابتعد عن الخانات الواقعة بين قطعتين للخصم.' },
  'b_reloc.y.y': { ja: 'よし。ここから、もう一度内側をめざします。', en: 'Good — from here it starts the walk inwards again.', zh: '好。从这里重新向内进发。', ko: '좋아요. 여기서 다시 안쪽을 향합니다.', es: 'Bien: desde aquí empieza de nuevo el camino hacia dentro.', fr: 'Bien — d’ici il repart vers l’intérieur.', pt: 'Boa — daqui ele recomeça a caminhada para dentro.', de: 'Gut — von hier beginnt der Weg nach innen von Neuem.', hi: 'अच्छा — यहाँ से वह फिर अंदर की यात्रा शुरू करता है।', ar: 'جيد — من هنا يبدأ طريقه إلى الداخل من جديد.' },
  'b_safe.e.t': { ja: '危ない駒を守る', en: 'Saving a piece in danger', zh: '保护危险的棋子', ko: '위험한 말 지키기', es: 'Salvar una pieza en peligro', fr: 'Sauver une pièce menacée', pt: 'Salvar uma peça em perigo', de: 'Einen bedrohten Stein retten', hi: 'ख़तरे वाली गोटी बचाना', ar: 'إنقاذ قطعة مهددة', ru: 'Спасти фигуру под угрозой', 'zh-TW': '救出危險的棋子', id: 'Menyelamatkan bidak terancam', tr: 'Tehlikedeki taşı kurtar' },
  'b_safe.e.b': { ja: '相手の次の1手で<b>はさまれる駒</b>（赤い枠）は、捕まると外周まで戻され、さらに置き直しで1手失います。\n守り方は2つ。<b>その駒を動かす</b>か、<b>相手が入ってくるマスを先にふさぐ</b>か。動かす先が<b>また別の駒にはさまれないか</b>も確かめます。', en: 'A piece that the opponent can <b>sandwich with its next move</b> (red frame) would be sent back to the edge and cost you a turn to relocate.\nTwo ways to save it: <b>move it away</b>, or <b>fill the cell the enemy would move into</b>. Check that the new cell is <b>not between two enemy pieces</b> again.', zh: '会被对方下一步<b>夹住的棋子</b>（红框）一旦被吃，就会被送回外圈，还要花一手来重新放置。\n保护方法有两种：<b>把它移开</b>，或<b>先占住对方要进入的格子</b>。还要确认移动后的格子<b>不会又被两枚敌子夹住</b>。', ko: '상대의 다음 한 수로 <b>끼일 말</b>(빨간 테두리)은 잡히면 바깥 고리로 돌아가고, 재배치로 한 수를 더 잃습니다.\n지키는 법은 두 가지. <b>그 말을 옮기거나</b>, <b>상대가 들어올 칸을 먼저 막거나</b>. 옮긴 칸이 <b>또 상대 말 2개 사이가 아닌지</b>도 확인하세요.', es: 'Una pieza que el rival puede <b>encerrar con su próxima jugada</b> (marco rojo) volvería al borde y te costaría un turno recolocarla.\nDos formas de salvarla: <b>apartarla</b> o <b>tapar la casilla a la que entraría el enemigo</b>. Comprueba que la nueva casilla <b>no esté otra vez entre dos piezas enemigas</b>.', fr: 'Une pièce que l’adversaire peut <b>prendre en tenaille au prochain coup</b> (cadre rouge) serait renvoyée au bord et vous coûterait un tour de replacement.\nDeux façons de la sauver : <b>la déplacer</b>, ou <b>occuper la case où l’ennemi entrerait</b>. Vérifiez que la nouvelle case <b>n’est pas de nouveau entre deux pièces ennemies</b>.', pt: 'Uma peça que o adversário pode <b>cercar no próximo lance</b> (moldura vermelha) voltaria para a borda e custaria um turno de recolocação.\nDuas formas de salvá-la: <b>tirá-la dali</b> ou <b>ocupar a casa em que o inimigo entraria</b>. Confira se a nova casa <b>não fica de novo entre duas peças inimigas</b>.', de: 'Ein Stein, den der Gegner <b>mit seinem nächsten Zug einschließen kann</b> (roter Rahmen), käme zurück an den Rand und kostete dich einen Zug zum Neusetzen.\nZwei Wege, ihn zu retten: <b>ihn wegziehen</b> oder <b>das Feld besetzen, auf das der Gegner ziehen würde</b>. Prüfe, dass das neue Feld <b>nicht wieder zwischen zwei gegnerischen Steinen</b> liegt.', hi: 'जिस गोटी को विरोधी <b>अपनी अगली चाल में फँसा सकता है</b> (लाल फ्रेम), वह बाहरी घेरे पर लौट जाएगी और दोबारा रखने में आपकी एक बारी जाएगी।\nबचाने के दो तरीक़े: <b>उसे हटा दें</b>, या <b>वह खाना भर दें जिसमें विरोधी आएगा</b>। जाँचें कि नया खाना <b>फिर से दो विरोधी गोटियों के बीच न हो</b>।', ar: 'القطعة التي يستطيع الخصم <b>محاصرتها بنقلته التالية</b> (الإطار الأحمر) ستعود إلى الحلقة الخارجية وتكلّفك دورًا لإعادة وضعها.\nطريقتان لإنقاذها: <b>أبعدها</b>، أو <b>املأ الخانة التي سيدخلها الخصم</b>. تأكد أن الخانة الجديدة <b>ليست مرة أخرى بين قطعتين للخصم</b>.', ru: 'Фигуру, которую соперник может <b>зажать следующим ходом</b> (красная рамка), отправят на край, и вы потеряете ход на перестановку.\nДва способа её спасти: <b>увести</b> или <b>занять клетку, куда пошёл бы соперник</b>. Проверьте, что новая клетка снова <b>не между двумя фигурами соперника</b>.', 'zh-TW': '對手<b>下一手就能夾住</b>的棋子（紅框）會被送回外圈，你還要花一手重新擺放。\n救法有兩種：<b>把它移開</b>，或<b>先占住敵方要走進的格子</b>。確認新的格子<b>不在兩枚敵子之間</b>。', id: 'Bidak yang bisa <b>dijepit lawan dengan langkah berikutnya</b> (bingkai merah) akan dikirim ke tepi dan kamu kehilangan giliran untuk memindahkannya.\nDua cara menyelamatkannya: <b>pindahkan</b>, atau <b>isi petak yang akan dimasuki lawan</b>. Pastikan petak baru <b>tidak di antara dua bidak lawan</b> lagi.', tr: 'Rakibin <b>sonraki hamlesiyle sıkıştırabileceği</b> taş (kırmızı çerçeve) kenara yollanır ve yeniden koymak sana bir tura mal olur.\nKurtarmanın iki yolu var: <b>uzaklaştır</b> ya da <b>rakibin gireceği kareyi doldur</b>. Yeni karenin yine <b>iki rakip taşın arasında olmadığını</b> kontrol et.' },
  'b_safe.y.g': { ja: '危ない駒を守ろう（指したあと、どの駒も捕まらないように）。', en: 'Save the piece in danger (after your move nothing can be captured).', zh: '保护危险的棋子（走完后，你的棋子都不会被吃）。', ko: '위험한 말을 지키세요(둔 뒤 어떤 말도 잡히지 않게).', es: 'Salva la pieza en peligro (tras tu jugada no puede haber capturas).', fr: 'Sauvez la pièce menacée (après votre coup, rien ne peut être capturé).', pt: 'Salve a peça em perigo (depois do seu lance nada pode ser capturado).', de: 'Rette den bedrohten Stein (nach deinem Zug kann nichts geschlagen werden).', hi: 'ख़तरे वाली गोटी बचाएँ (आपकी चाल के बाद कुछ भी पकड़ा न जा सके)।', ar: 'أنقذ القطعة المهددة (بعد نقلتك لا يمكن أسر شيء).', ru: 'Спасите фигуру под угрозой (после вашего хода брать нечего).', 'zh-TW': '救出危險的棋子（走完後沒有棋子會被吃）。', id: 'Selamatkan bidak terancam (setelah langkahmu tak ada yang bisa ditangkap).', tr: 'Tehlikedeki taşı kurtar (hamlenden sonra alınacak taş kalmasın).' },
  'b_safe.y.h': { ja: '相手がどこへ動けばはさめるかを先に見ます。', en: 'First find where the enemy would move to sandwich it.', zh: '先找出对方走到哪里就能夹住它。', ko: '상대가 어디로 움직이면 끼울 수 있는지 먼저 보세요.', es: 'Primero busca adónde iría el enemigo para encerrarla.', fr: 'Trouvez d’abord où l’ennemi irait pour la prendre en tenaille.', pt: 'Primeiro descubra para onde o inimigo iria para cercá-la.', de: 'Finde zuerst, wohin der Gegner ziehen würde, um ihn einzuschließen.', hi: 'पहले पता करें कि विरोधी उसे फँसाने कहाँ जाएगा।', ar: 'اعرف أولًا إلى أين سيتحرك الخصم ليحاصرها.', ru: 'Сначала найдите, куда сходит соперник, чтобы зажать её.', 'zh-TW': '先找出敵方要走到哪裡才能夾住它。', id: 'Cari dulu ke mana lawan akan bergerak untuk menjepitnya.', tr: 'Önce rakibin onu sıkıştırmak için nereye gideceğini bul.' },
  'b_safe.y.y': { ja: '安全です。相手は捕獲できません。', en: 'Safe — your opponent has no capture now.', zh: '安全了。对方无子可吃。', ko: '안전합니다. 상대는 잡을 수 없습니다.', es: 'A salvo: tu rival ya no tiene captura.', fr: 'En sécurité — l’adversaire n’a plus de capture.', pt: 'Segura — seu adversário não tem captura agora.', de: 'Sicher — dein Gegner hat jetzt keinen Schlag.', hi: 'सुरक्षित — अब विरोधी के पास कोई पकड़ नहीं।', ar: 'آمنة — لا يملك خصمك أسرًا الآن.', ru: 'В безопасности — у соперника теперь нет взятий.', 'zh-TW': '安全了 — 對手現在沒有吃子機會。', id: 'Aman — lawan sekarang tidak punya penangkapan.', tr: 'Güvende — rakibin artık alması yok.' },
  'b_finish.e.t': { ja: '勝ちの形', en: 'The winning shape', zh: '获胜的形状', ko: '승리의 형태', es: 'La forma ganadora', fr: 'La figure gagnante', pt: 'A forma vencedora', de: 'Die Gewinnfigur', hi: 'जीत का आकार', ar: 'شكل الفوز', ru: 'Выигрышная фигура', 'zh-TW': '獲勝的形狀', id: 'Bentuk kemenangan', tr: 'Kazanan şekil' },
  'b_finish.e.b': { ja: '<b>女王が王座に座り、周りの6マスがすべて自分のガード</b>になった瞬間に勝ちです。\n逆に、<b>王座が空っぽ（または相手の女王）のまま自分のガード6枚で囲むと、その場で負け</b>。女王を先に王座へ入れてから囲みましょう。', en: 'You win the moment <b>your queen sits on the throne and all six cells round her hold your guards</b>.\nBut <b>six of your guards round an empty throne (or round the enemy queen) lose at once</b> — so the queen goes in first, then the ring is closed.', zh: '<b>女王坐在王座上，周围6格全是你的卫兵</b>的那一刻即获胜。\n反过来，<b>王座空着（或坐着对方女王）时用自己的6个卫兵围住，就立即判负</b>。所以先让女王进王座，再围住。', ko: '<b>여왕이 왕좌에 앉고 둘레 6칸이 모두 내 호위병</b>이 되는 순간 승리합니다.\n반대로 <b>왕좌가 빈 채(또는 상대 여왕이 있는 채) 내 호위병 6개로 둘러싸면 그 즉시 패배</b>. 여왕을 먼저 왕좌에 넣은 뒤 둘러싸세요.', es: 'Ganas en cuanto <b>tu reina se sienta en el trono y las seis casillas a su alrededor tienen tus guardias</b>.\nPero <b>seis guardias tuyos alrededor de un trono vacío (o de la reina rival) pierden en el acto</b>: primero entra la reina y luego se cierra el anillo.', fr: 'Vous gagnez dès que <b>votre reine siège sur le trône et que les six cases autour d’elle sont occupées par vos gardes</b>.\nMais <b>six de vos gardes autour d’un trône vide (ou de la reine adverse) perdent immédiatement</b> — la reine entre donc d’abord, puis l’anneau se ferme.', pt: 'Você vence no momento em que <b>sua rainha se senta no trono e as seis casas ao redor dela têm seus guardas</b>.\nMas <b>seis guardas seus ao redor de um trono vazio (ou da rainha inimiga) perdem na hora</b> — então a rainha entra primeiro, depois o anel se fecha.', de: 'Du gewinnst in dem Moment, in dem <b>deine Königin auf dem Thron sitzt und alle sechs Felder um sie deine Wachen tragen</b>.\nAber <b>sechs deiner Wachen um einen leeren Thron (oder um die gegnerische Königin) verlieren sofort</b> — also zuerst die Königin hinein, dann den Ring schließen.', hi: 'जिस पल <b>आपकी रानी सिंहासन पर बैठी हो और उसके चारों ओर के छहों खानों पर आपके रक्षक हों</b>, आप जीत जाते हैं।\nपर <b>ख़ाली सिंहासन (या विरोधी रानी) के चारों ओर आपके छह रक्षक हों तो तुरंत हार</b> — इसलिए पहले रानी अंदर, फिर घेरा पूरा।', ar: 'تفوز في اللحظة التي <b>تجلس فيها ملكتك على العرش وتشغل حراسُك الخانات الست كلها حولها</b>.\nلكن <b>ستة من حراسك حول عرش فارغ (أو حول ملكة الخصم) تخسر فورًا</b> — لذلك تدخل الملكة أولًا ثم تُغلق الحلقة.', ru: 'Вы побеждаете, как только <b>ваша королева сидит на троне, а на всех шести клетках вокруг стоят ваши стражи</b>.\nНо <b>шесть ваших стражей вокруг пустого трона (или королевы соперника) — сразу поражение</b>, поэтому сначала входит королева, затем замыкается кольцо.', 'zh-TW': '當<b>你的女王坐在王座上，周圍六格全是你的衛兵</b>時，立刻獲勝。\n但<b>你的六名衛兵圍住空的王座（或敵方女王）會立刻判負</b> — 所以先讓女王進去，再完成包圍。', id: 'Kamu menang saat <b>ratumu duduk di takhta dan keenam petak di sekelilingnya diisi pengawalmu</b>.\nTetapi <b>enam pengawalmu di sekitar takhta kosong (atau ratu lawan) langsung kalah</b> — jadi ratu masuk dulu, lalu cincin ditutup.', tr: '<b>Kraliçen tahtta otururken çevresindeki altı karenin hepsinde muhafızların</b> olduğu an kazanırsın.\nAma <b>boş tahtın (ya da rakip kraliçenin) çevresindeki altı muhafızın hemen kaybettirir</b> — bu yüzden önce kraliçe girer, sonra halka kapanır.' },
  's_block.e.t': { ja: '相手の完成をふせぐ', en: 'Stopping the opponent’s ring', zh: '阻止对方完成', ko: '상대의 완성 막기', es: 'Frenar el anillo rival', fr: 'Arrêter l’anneau adverse', pt: 'Parar o anel do adversário', de: 'Den gegnerischen Ring stoppen', hi: 'विरोधी का घेरा रोकना', ar: 'إيقاف حلقة الخصم', ru: 'Остановить кольцо соперника', 'zh-TW': '阻止對手的包圍', id: 'Menghentikan cincin lawan', tr: 'Rakibin halkasını durdur' },
  's_block.e.b': { ja: '相手の女王が王座にいて、周りの5マスが相手のガード。最後の1枚（赤い枠）が入れば負けです。\n残った1マスは<b>相手の駒2枚にはさまれた「入れないマス」</b>（×）なので、自分の駒でふさぐことはできません。止める手は<b>入ってくるガードを捕まえる</b>か、<b>輪のガードや王座の女王を捕まえる</b>こと。', en: 'The enemy queen is on the throne with five guards round her: the sixth (red frame) would win next move.\nThe last cell lies <b>between two enemy pieces</b> (×), so you may not move in to block it. Stop the ring by <b>capturing the incoming guard</b> — or a guard of the ring, or the queen on the throne.', zh: '对方女王在王座上，周围5格是对方的卫兵。最后一枚（红框）进来你就输了。\n剩下的一格<b>被两枚敌子夹着，是“不能进入的格子”</b>（×），所以你无法用棋子堵住。阻止的办法是<b>吃掉要进来的卫兵</b>，或者吃掉圈上的卫兵或王座上的女王。', ko: '상대 여왕이 왕좌에 있고 둘레 5칸이 상대 호위병. 마지막 하나(빨간 테두리)가 들어오면 패배입니다.\n남은 한 칸은 <b>상대 말 2개 사이의 "들어갈 수 없는 칸"</b>(×)이라 내 말로 막을 수 없습니다. 막는 방법은 <b>들어오는 호위병을 잡는 것</b>. 고리의 호위병이나 왕좌의 여왕을 잡아도 됩니다.', es: 'La reina rival está en el trono con cinco guardias alrededor: el sexto (marco rojo) ganaría en la próxima jugada.\nLa última casilla está <b>entre dos piezas enemigas</b> (×), así que no puedes entrar para taparla. Frena el anillo <b>capturando al guardia que llega</b>, o a un guardia del anillo, o a la reina del trono.', fr: 'La reine adverse est sur le trône avec cinq gardes autour : le sixième (cadre rouge) gagnerait au prochain coup.\nLa dernière case est <b>entre deux pièces ennemies</b> (×) : vous ne pouvez pas y entrer pour la bloquer. Arrêtez l’anneau en <b>capturant le garde qui arrive</b> — ou un garde de l’anneau, ou la reine sur le trône.', pt: 'A rainha inimiga está no trono com cinco guardas ao redor: o sexto (moldura vermelha) venceria no próximo lance.\nA última casa fica <b>entre duas peças inimigas</b> (×), então você não pode entrar nela para bloquear. Pare o anel <b>capturando o guarda que está chegando</b> — ou um guarda do anel, ou a rainha no trono.', de: 'Die gegnerische Königin sitzt auf dem Thron, fünf Wachen um sie: Die sechste (roter Rahmen) würde im nächsten Zug gewinnen.\nDas letzte Feld liegt <b>zwischen zwei gegnerischen Steinen</b> (×), also darfst du nicht hineinziehen, um es zu blockieren. Stoppe den Ring, indem du <b>die ankommende Wache schlägst</b> — oder eine Wache des Rings oder die Königin auf dem Thron.', hi: 'विरोधी रानी सिंहासन पर है और उसके चारों ओर पाँच रक्षक हैं: छठा (लाल फ्रेम) अगली चाल में जीत जाएगा।\nआख़िरी खाना <b>दो विरोधी गोटियों के बीच</b> (×) है, इसलिए आप उसे रोकने के लिए उसमें नहीं जा सकते। घेरा रोकें <b>आते हुए रक्षक को पकड़कर</b> — या घेरे के किसी रक्षक को, या सिंहासन पर बैठी रानी को।', ar: 'ملكة الخصم على العرش وحولها خمسة حراس: السادس (الإطار الأحمر) سيفوز في النقلة التالية.\nالخانة الأخيرة تقع <b>بين قطعتين للخصم</b> (×)، فلا يجوز لك دخولها لسدّها. أوقف الحلقة <b>بأسر الحارس القادم</b> — أو حارس من الحلقة، أو الملكة على العرش.', ru: 'Королева соперника на троне, вокруг пять стражей: шестой (красная рамка) победит следующим ходом.\nПоследняя клетка лежит <b>между двумя фигурами соперника</b> (×), поэтому встать туда нельзя. Остановите кольцо, <b>взяв входящего стража</b> — или стража из кольца, или королеву на троне.', 'zh-TW': '敵方女王在王座上，周圍有五名衛兵：第六名（紅框）下一手就會獲勝。\n最後一格位於<b>兩枚敵子之間</b>（×），不能走進去擋。要<b>吃掉正要進來的衛兵</b> — 或包圍中的衛兵、或王座上的女王 — 來阻止包圍。', id: 'Ratu lawan di takhta dengan lima pengawal di sekelilingnya: yang keenam (bingkai merah) akan menang di langkah berikut.\nPetak terakhir berada <b>di antara dua bidak lawan</b> (×), jadi kamu tidak boleh masuk untuk menghalanginya. Hentikan cincin dengan <b>menangkap pengawal yang datang</b> — atau pengawal di cincin, atau ratu di takhta.', tr: 'Rakip kraliçe tahtta, çevresinde beş muhafız var: altıncı (kırmızı çerçeve) bir sonraki hamlede kazanır.\nSon kare <b>iki rakip taşın arasında</b> (×), bu yüzden girip engelleyemezsin. Halkayı <b>gelen muhafızı alarak</b> durdur — ya da halkadaki bir muhafızı veya tahttaki kraliçeyi.' },
  's_block.y.g': { ja: '相手の完成を止めよう。', en: 'Stop the enemy from completing its ring.', zh: '阻止对方完成包围。', ko: '상대의 완성을 막으세요.', es: 'Impide que el rival complete su anillo.', fr: 'Empêchez l’adversaire de compléter son anneau.', pt: 'Impeça o inimigo de completar o anel.', de: 'Hindere den Gegner daran, seinen Ring zu schließen.', hi: 'विरोधी को घेरा पूरा करने से रोकें।', ar: 'امنع الخصم من إكمال حلقته.', ru: 'Не дайте сопернику замкнуть кольцо.', 'zh-TW': '阻止敵方完成包圍。', id: 'Cegah lawan melengkapi cincinnya.', tr: 'Rakibin halkasını tamamlamasını engelle.' },
  's_block.y.h': { ja: '入ってこようとしているガードを、一直線にはさめるマスを探します。', en: 'Find a cell from which you sandwich the incoming guard in a line.', zh: '找一个能在一条直线上夹住要进来的卫兵的格子。', ko: '들어오려는 호위병을 한 줄로 끼울 수 있는 칸을 찾으세요.', es: 'Busca una casilla desde la que encierres en línea al guardia que llega.', fr: 'Trouvez une case d’où vous prenez en tenaille, sur une ligne, le garde qui arrive.', pt: 'Ache uma casa de onde você cerca em linha o guarda que está chegando.', de: 'Finde ein Feld, von dem aus du die ankommende Wache in einer Linie einschließt.', hi: 'ऐसा खाना ढूँढें जहाँ से आप आते हुए रक्षक को एक रेखा में फँसा सकें।', ar: 'جد خانة تحاصر منها الحارس القادم على خط.', ru: 'Найдите клетку, с которой входящий страж зажимается на линии.', 'zh-TW': '找一格能在一直線上夾住那名要進來的衛兵。', id: 'Cari petak dari mana kamu menjepit pengawal yang datang dalam satu garis.', tr: 'Gelen muhafızı bir çizgide sıkıştıracağın kareyi bul.' },
  's_block.y.y': { ja: 'これで相手はすぐには勝てません。', en: 'Now the enemy cannot win at once.', zh: '这样对方就无法马上获胜了。', ko: '이제 상대는 바로 이길 수 없습니다.', es: 'Ahora el rival no puede ganar enseguida.', fr: 'L’adversaire ne peut plus gagner aussitôt.', pt: 'Agora o inimigo não pode vencer logo.', de: 'Jetzt kann der Gegner nicht sofort gewinnen.', hi: 'अब विरोधी तुरंत नहीं जीत सकता।', ar: 'الآن لا يستطيع الخصم الفوز فورًا.', ru: 'Теперь соперник не может сразу победить.', 'zh-TW': '現在敵方無法馬上獲勝了。', id: 'Sekarang lawan tidak bisa langsung menang.', tr: 'Artık rakip hemen kazanamaz.' },
  's_queencap.e.t': { ja: '王座の女王も捕まえられる', en: 'Even the queen on the throne can be captured', zh: '王座上的女王也能吃', ko: '왕좌의 여왕도 잡을 수 있다', es: 'Hasta la reina en el trono se puede capturar', fr: 'Même la reine sur le trône peut être capturée', pt: 'Até a rainha no trono pode ser capturada', de: 'Selbst die Königin auf dem Thron kann geschlagen werden', hi: 'सिंहासन पर बैठी रानी भी पकड़ी जा सकती है', ar: 'حتى الملكة على العرش يمكن أسرها', ru: 'Даже королеву на троне можно взять', 'zh-TW': '王座上的女王也能吃', id: 'Ratu di takhta pun bisa ditangkap', tr: 'Tahttaki kraliçe bile alınabilir' },
  's_queencap.e.b': { ja: '王座の女王も、<b>向かい合う2つのマス</b>（王座をはさんで一直線）を自分の駒でうめれば捕獲できます。\n捕まった女王は王座を出て別の空きマスへ置き直し。<b>王座が空くので、相手の完成は大きく遠のきます</b>。', en: 'The queen on the throne is captured too when <b>two of your pieces stand on opposite cells</b> (in a line through the throne).\nShe must then leave the throne for another empty cell — <b>the throne is free again and the enemy’s ring is far away</b>.', zh: '王座上的女王，只要你的棋子占住<b>相对的两格</b>（隔着王座成一直线），也能被吃掉。\n被吃的女王要离开王座重新放置到别的空格。<b>王座空了出来，对方的完成就大大推迟了</b>。', ko: '왕좌의 여왕도 <b>마주 보는 두 칸</b>(왕좌를 사이에 둔 한 줄)을 내 말로 채우면 잡을 수 있습니다.\n잡힌 여왕은 왕좌를 떠나 다른 빈칸에 재배치됩니다. <b>왕좌가 비므로 상대의 완성은 크게 멀어집니다</b>.', es: 'La reina en el trono también queda capturada cuando <b>dos piezas tuyas ocupan casillas opuestas</b> (en línea a través del trono).\nEntonces debe dejar el trono por otra casilla vacía: <b>el trono queda libre y el anillo rival, lejos</b>.', fr: 'La reine sur le trône est capturée elle aussi quand <b>deux de vos pièces occupent des cases opposées</b> (sur une ligne passant par le trône).\nElle doit alors quitter le trône pour une autre case vide — <b>le trône est de nouveau libre et l’anneau adverse loin</b>.', pt: 'A rainha no trono também é capturada quando <b>duas peças suas ocupam casas opostas</b> (numa linha que passa pelo trono).\nEla precisa então deixar o trono por outra casa vazia — <b>o trono fica livre de novo e o anel inimigo fica longe</b>.', de: 'Auch die Königin auf dem Thron wird geschlagen, wenn <b>zwei deiner Steine auf gegenüberliegenden Feldern stehen</b> (in einer Linie durch den Thron).\nSie muss dann den Thron für ein anderes freies Feld verlassen — <b>der Thron ist wieder frei und der gegnerische Ring weit weg</b>.', hi: 'सिंहासन पर बैठी रानी भी पकड़ी जाती है जब <b>आपकी दो गोटियाँ आमने-सामने के खानों पर हों</b> (सिंहासन से होकर एक रेखा में)।\nतब उसे सिंहासन छोड़कर किसी और खाली खाने पर जाना होता है — <b>सिंहासन फिर ख़ाली और विरोधी का घेरा दूर</b>।', ar: 'تُؤسر الملكة على العرش أيضًا حين <b>تقف قطعتان لك في خانتين متقابلتين</b> (على خط يمر بالعرش).\nعندئذ يجب أن تغادر العرش إلى خانة فارغة أخرى — <b>فيصبح العرش حرًا من جديد وتبتعد حلقة الخصم</b>.', ru: 'Королеву на троне тоже берут, когда <b>две ваши фигуры стоят на противоположных клетках</b> (на линии через трон).\nТогда ей придётся покинуть трон и встать на другую пустую клетку — <b>трон снова свободен, а кольцо соперника далеко</b>.', 'zh-TW': '當<b>你的兩枚棋子站在相對的格子</b>（穿過王座的一直線）時，王座上的女王也會被吃。\n她必須離開王座到別的空格 — <b>王座又空了，敵方的包圍也變遠了</b>。', id: 'Ratu di takhta juga tertangkap saat <b>dua bidakmu berdiri di petak berseberangan</b> (dalam garis melewati takhta).\nIa harus meninggalkan takhta ke petak kosong lain — <b>takhta kosong lagi dan cincin lawan jauh</b>.', tr: 'Tahttaki kraliçe de <b>iki taşın karşılıklı karelerde durunca</b> (tahttan geçen bir çizgide) alınır.\nO zaman tahtı bırakıp başka boş bir kareye gitmeli — <b>taht yine boş ve rakibin halkası uzakta</b>.' },
  's_queencap.y.g': { ja: '王座の女王を捕まえよう。', en: 'Capture the queen on the throne.', zh: '吃掉王座上的女王。', ko: '왕좌의 여왕을 잡으세요.', es: 'Captura a la reina en el trono.', fr: 'Capturez la reine sur le trône.', pt: 'Capture a rainha no trono.', de: 'Schlage die Königin auf dem Thron.', hi: 'सिंहासन पर बैठी रानी को पकड़ें।', ar: 'قم بأسر الملكة على العرش.', ru: 'Возьмите королеву на троне.', 'zh-TW': '吃掉王座上的女王。', id: 'Tangkap ratu di takhta.', tr: 'Tahttaki kraliçeyi al.' },
  's_queencap.y.h': { ja: '1の輪で、自分の駒の真向かい（王座の反対側）のマスへ。', en: 'On ring 1, move to the cell straight across the throne from one of your pieces.', zh: '在第1圈，走到隔着王座正对你一枚棋子的格子。', ko: '1번 고리에서, 내 말의 정반대편(왕좌 건너편) 칸으로.', es: 'En el anillo 1, ve a la casilla justo enfrente de una pieza tuya, al otro lado del trono.', fr: 'Sur l’anneau 1, allez sur la case juste en face d’une de vos pièces, de l’autre côté du trône.', pt: 'No anel 1, vá para a casa bem em frente a uma peça sua, do outro lado do trono.', de: 'Ziehe auf Ring 1 auf das Feld, das einem deiner Steine über den Thron hinweg genau gegenüberliegt.', hi: 'घेरा 1 पर, सिंहासन के पार अपनी किसी गोटी के ठीक सामने वाले खाने पर जाएँ।', ar: 'على الحلقة 1، انتقل إلى الخانة المقابلة تمامًا لإحدى قطعك عبر العرش.', ru: 'На кольце 1 встаньте на клетку напротив одной из своих фигур через трон.', 'zh-TW': '在第1圈，走到隔著王座與己方棋子正對的格子。', id: 'Di cincin 1, bergeraklah ke petak yang berseberangan lurus melewati takhta dari salah satu bidakmu.', tr: '1. halkada, taşlarından birinin tahtın tam karşısındaki kareye git.' },
  's_queencap.y.y': { ja: '女王を王座から追い出しました！', en: 'The queen is driven off the throne!', zh: '把女王赶下了王座！', ko: '여왕을 왕좌에서 쫓아냈습니다!', es: '¡La reina sale echada del trono!', fr: 'La reine est chassée du trône !', pt: 'A rainha foi expulsa do trono!', de: 'Die Königin ist vom Thron vertrieben!', hi: 'रानी सिंहासन से हटा दी गई!', ar: 'طُردت الملكة من العرش!', ru: 'Королева согнана с трона!', 'zh-TW': '女王被趕下王座了！', id: 'Ratu terusir dari takhta!', tr: 'Kraliçe tahttan indirildi!' },
  's_win2.e.t': { ja: '2手先まで読む', en: 'Looking two moves ahead', zh: '算到两步之后', ko: '두 수 앞까지 읽기', es: 'Mirar dos jugadas adelante', fr: 'Voir deux coups à l’avance', pt: 'Olhar dois lances à frente', de: 'Zwei Züge vorausdenken', hi: 'दो चालें आगे देखना', ar: 'النظر نقلتين إلى الأمام', ru: 'Расчёт на два хода вперёд', 'zh-TW': '往後看兩步', id: 'Melihat dua langkah ke depan', tr: 'İki hamle ileriyi görmek' },
  's_win2.e.b': { ja: '勝ちまで2手。ただし相手も1手指します。<b>相手がどう受けても間に合う手</b>を探しましょう。\n先に女王を王座へ入れるのか、ガードを内側へ入れるのか。相手が入れるマス・はさめる形を先に消しておくのがコツです。', en: 'Two moves to win — but your opponent moves in between. Find the move that works <b>whatever the reply</b>.\nQueen to the throne first, or a guard in? Take away the cells the enemy could block and the sandwiches it could make.', zh: '再走两步就能赢，但对方中间也会走一步。找出<b>无论对方怎么应对都来得及的一步</b>。\n先让女王进王座，还是先让卫兵向内？诀窍是先消除对方能进入的格子和能夹住的形状。', ko: '승리까지 두 수. 하지만 상대도 한 수를 둡니다. <b>상대가 어떻게 받아도 늦지 않는 수</b>를 찾으세요.\n여왕을 먼저 왕좌에 넣을지, 호위병을 먼저 안으로 넣을지. 상대가 들어올 칸과 끼울 형태를 먼저 없애는 것이 요령입니다.', es: 'Faltan dos jugadas para ganar, pero el rival juega entre medias. Busca la jugada que funciona <b>responda lo que responda</b>.\n¿Primero la reina al trono, o un guardia hacia dentro? Quítale al enemigo las casillas que podría tapar y los encierros que podría hacer.', fr: 'Deux coups pour gagner — mais l’adversaire joue entre-temps. Trouvez le coup qui marche <b>quelle que soit la réponse</b>.\nLa reine au trône d’abord, ou un garde vers l’intérieur ? Ôtez à l’ennemi les cases qu’il pourrait bloquer et les tenailles qu’il pourrait faire.', pt: 'Dois lances para vencer — mas o adversário joga no meio. Ache o lance que funciona <b>seja qual for a resposta</b>.\nRainha no trono primeiro, ou um guarda para dentro? Tire do inimigo as casas que ele poderia bloquear e os cercos que poderia fazer.', de: 'Zwei Züge bis zum Sieg — aber dazwischen zieht der Gegner. Finde den Zug, der <b>gegen jede Antwort</b> funktioniert.\nZuerst die Königin auf den Thron oder eine Wache nach innen? Nimm dem Gegner die Felder, die er blockieren könnte, und die Einschließungen, die er machen könnte.', hi: 'जीत के लिए दो चालें — पर बीच में विरोधी भी चलता है। वह चाल ढूँढें जो <b>हर जवाब के बावजूद</b> काम करे।\nपहले रानी सिंहासन पर, या पहले कोई रक्षक अंदर? विरोधी से वे खाने छीन लें जिन्हें वह रोक सकता है, और वे फँसाव जो वह कर सकता है।', ar: 'نقلتان للفوز — لكن الخصم يلعب بينهما. جد النقلة التي تنجح <b>مهما كان الرد</b>.\nالملكة إلى العرش أولًا، أم حارس إلى الداخل؟ انزع من الخصم الخانات التي قد يسدّها والمحاصرات التي قد يصنعها.', ru: 'До победы два хода — но между ними ходит соперник. Найдите ход, который работает <b>при любом ответе</b>.\nСначала королеву на трон или стража внутрь? Отнимите у соперника клетки для блока и возможности зажать.', 'zh-TW': '還差兩步就贏 — 但中間對手也會走。找出<b>不論對手怎麼應</b>都成立的著法。\n先讓女王上王座，還是先讓衛兵進去？先封掉敵方能擋的格子和能夾的機會。', id: 'Dua langkah untuk menang — tetapi lawan bergerak di antaranya. Temukan langkah yang berhasil <b>apa pun balasannya</b>.\nRatu ke takhta dulu, atau pengawal masuk? Ambil petak yang bisa dipakai lawan untuk menghalangi dan peluang jepitnya.', tr: 'Kazanmaya iki hamle var — ama arada rakip de oynar. <b>Cevap ne olursa olsun</b> işe yarayan hamleyi bul.\nÖnce kraliçe tahta mı, yoksa muhafız içeri mi? Rakibin engelleyebileceği kareleri ve yapabileceği sıkıştırmaları elinden al.' },
};
